-- =====================================================================
-- Astra ground station databases (AstraConfig + AstraTestLog)
-- 01 - schemas, tables, keys, defaults, indexes, foreign keys
-- Dialect: PostgreSQL 13+ (tested on 16), run with psql -v ON_ERROR_STOP=1
-- Generated 2026-10-03 17:41  from SQL Server 2016 (13.0.4001) full backups
-- AstraConfig.bak (2017-07-05) and AstraTestLog.bak (2017-04-12).
-- =====================================================================

SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SET client_min_messages = warning;

-- AstraConfig.dbo -> schema config ; AstraTestLog.dbo -> schema testlog (one PG database, so the old
-- cross-database three-part names AstraConfig.dbo.X / AstraTestLog.dbo.X become config.x / testlog.x).
-- Identifiers are the original names folded to lower case (unquoted where possible), so unquoted Delphi SQL
-- such as SELECT * FROM VarTypes keeps working when search_path includes the schema.

CREATE SCHEMA IF NOT EXISTS config;
COMMENT ON SCHEMA config IS 'Migrated from SQL Server database AstraConfig (schema dbo)';
-- Sort order of SQL_Latin1_General_CP1_CI_AS: punctuation significant and sorted before digits and letters
-- (e.g. 'parkerStep_t' < 'parkerStepSustDuty'). glibc locales such as en_US.UTF-8 ignore punctuation and would
-- reorder fields with equal Seq in spGetInterface/spGetVarTypeFields (= packet layout). Requires PG built with ICU.
-- Deterministic: '=' stays case-sensitive (SQL Server compares case-insensitively; see README).
CREATE COLLATION IF NOT EXISTS config.mssql_order (provider = icu, locale = 'und-u-ka-noignore');

CREATE SCHEMA IF NOT EXISTS testlog;
COMMENT ON SCHEMA testlog IS 'Migrated from SQL Server database AstraTestLog (schema dbo)';
-- Sort order of SQL_Latin1_General_CP1_CI_AS: punctuation significant and sorted before digits and letters
-- (e.g. 'parkerStep_t' < 'parkerStepSustDuty'). glibc locales such as en_US.UTF-8 ignore punctuation and would
-- reorder fields with equal Seq in spGetInterface/spGetVarTypeFields (= packet layout). Requires PG built with ICU.
-- Deterministic: '=' stays case-sensitive (SQL Server compares case-insensitively; see README).
CREATE COLLATION IF NOT EXISTS testlog.mssql_order (provider = icu, locale = 'und-u-ka-noignore');

