-- Foreign keys: DEFERRABLE INITIALLY IMMEDIATE (behaves exactly like a normal FK unless a session runs
-- SET CONSTRAINTS ... DEFERRED, which 02_data.sql does so tables can be loaded in any order).
ALTER TABLE config.actors ADD CONSTRAINT fk_actors_devices FOREIGN KEY (deviceid) REFERENCES config.devices (id) ON DELETE NO ACTION ON UPDATE NO ACTION DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE config.actors ADD CONSTRAINT fk_actors_tests FOREIGN KEY (testid) REFERENCES config.tests (id) ON DELETE CASCADE ON UPDATE CASCADE DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE config.areas ADD CONSTRAINT "areas$area_listareas" FOREIGN KEY (area_id) REFERENCES config.area_list (id) ON DELETE NO ACTION ON UPDATE NO ACTION DEFERRABLE INITIALLY IMMEDIATE;  -- was WITH NOCHECK (untrusted) in MSSQL; existing data verified clean
ALTER TABLE config.areas ADD CONSTRAINT "areas$stageareas" FOREIGN KEY (stage_id) REFERENCES config.stage (id) ON DELETE NO ACTION ON UPDATE NO ACTION DEFERRABLE INITIALLY IMMEDIATE;  -- was WITH NOCHECK (untrusted) in MSSQL; existing data verified clean
ALTER TABLE config.connections ADD CONSTRAINT fk_connections_linktypes FOREIGN KEY (linktypeid) REFERENCES config.linktypes (id) ON DELETE NO ACTION ON UPDATE NO ACTION DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE config.connections ADD CONSTRAINT fk_connections_treeversions FOREIGN KEY (boardid) REFERENCES config.treeversions (id) ON DELETE CASCADE ON UPDATE NO ACTION DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE config.connectors ADD CONSTRAINT "connectors$genderconnector_type" FOREIGN KEY (gender_id) REFERENCES config.connector_gender (id) ON DELETE NO ACTION ON UPDATE NO ACTION DEFERRABLE INITIALLY IMMEDIATE;  -- was WITH NOCHECK (untrusted) in MSSQL; existing data verified clean
