ALTER TABLE config.devices ADD CONSTRAINT fk_devices_treeversions FOREIGN KEY (smartnodeid) REFERENCES config.treeversions (id) ON DELETE NO ACTION ON UPDATE NO ACTION DEFERRABLE INITIALLY IMMEDIATE;
